head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pMenuID = "ULDSTF05201";
scwin.vPageTYp = '2';
/************************************************************************************
 * ID           :	ULDSTF05201
 * File         :	ULDSTF05201.xml
 * Name         :	변경상장
 * Author       :	배성우
 * Description  :
 * Create Date  :	2026-07-30
 ************************************************************************************/

// scwin.pMenuID = $c.stf.infoMenuID();
// scwin.fr_SecuGrpId = $c.lc.getSecuGrpId($c.stf.infoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fr_SecuGrpId = $c.lc.getSecuGrpId("STF05200"); // TODO: 기본값 주권인지 확인필요
scwin.market = $c.session.getUserInfo("market");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — searchCode, setSymblObj, readRecvComnmynSync, btn_search_onclick, setInsertStatus 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        $c.win.setEnterKeyEvent(grp_search, scwin.btn_search_onclick);
        if ($c.win.isPopup()) {
            scwin.getParam = $c.data.getParameter();
            scwin.pMenuID = $c.win.getParent().scwin.vScrenID;
            scwin.fr_SecuGrpId = $c.lc.getSecuGrpId(scwin.pMenuID);
        }
        await scwin.searchCode();
        // $c.libRoundPanel.PanelToGroupBox(panel_CoNmChg_Item);
        scwin.vSYMBL_INPUT_CD = scwin.market;
        scwin.setSymblObj();
        await MxTab_1.setSelectedTabIndex(1);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        // buttonSet.setSaveInfo(btn_save, fn_save); // 저장
        // buttonSet.setUpdateInfo(btn_update, fn_update); // 수정
        // buttonSet.setDeleteInfo(btn_delete, fn_delete); // 삭제
        // buttonSet.setDsclInfo(btn_dscl, fn_dscl); // 안내문작성

        // let parentWin = $c.lc.getRecvDocProvider();

        // if (scwin.gIsurCd != "" && scwin.gIsurCd != undefined) {
        if ($c.win.isPopup()) {
            ibx_isurCd.setValue(scwin.gIsurCd);
            ibx_comNm.setValue(scwin.gComAbbrv);

            scwin.fr_SecuGrpId = scwin.gSecugrpId;
            scwin.vSpotIsuTrdMktTpCd = scwin.gMktTpCd;

            // grid 헤드 세팅
            $c.lc.gridNameChange(scwin.fr_SecuGrpId, "grd_IssRecv", "grd_IssList");

            await scwin.readRecvComnmynSync(scwin.gAcptNo);

            if (dma_chkStkisuComynRes.get("checkYn") === 'Y') {
                MxTab_1.setSelectedTabIndex(0); // 상호변경탭으로 이동

            }
            // btn_search.trigger("onclick");
            scwin.btn_search_onclick();
        } else {
            // buttonSet.setInsertStatus();
            scwin.setInsertStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_isunmBatchChange_onclick
 * @description [상호변경] 종목명자동생성 버튼 — 「종목명자동생성」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_isunmBatchChange_onclick = function () {
    try {
        scwin.changeIsuNmByBatch();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05201.btn_isunmBatchChange_onclick" });
    }
};

/**
 * @method
 * @name sbx_comChgRsnCd_onselchange
 * @description sbx_comChgRsnCd 선택 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.sbx_comChgRsnCd_onselchange = function () {
    /*
    저장된내용의 변경사유가 영문상호변경이면 변경후가 변경전 회사내용으로 초기화되어 나중에 수정해야됨
        if (getObjectValue(sbx_comChgRsnCd) == "11" || getObjectValue(sbx_comChgRsnCd) == "12") {
            $c.win.alert("변경사유가 영문상호변경, 약명변경을 선택하면 \r\n\r\n변경후 회사정보는 변경전 회사정보로 자동설정되오니 변경항목만 수정하시면 됩니다.");

            ibx_afchgComNm.value = dts_CoNm.NameString(1, "BFCHG_COM_NM");
            ibx_afchgComAbbrv.value = dts_CoNm.NameString(1, "BFCHG_COM_ABBRV");
            ibx_afchgComEngNm.value = dts_CoNm.NameString(1, "BFCHG_COM_ENG_NM");
            ibx_afchgComEngAbbrv.value = dts_CoNm.NameString(1, "BFCHG_COM_ENG_ABBRV");
        } else {
            //ibx_afchgComNm.value = "";
            //ibx_afchgComAbbrv.value = "";
            //ibx_afchgComEngNm.value = "";
            //ibx_afchgComEngAbbrv.value = "";
        }
     */
};

/**
 * @method
 * @name btn_comNm_onclick
 * @description 회사코드 검색팝업 버튼
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_comNm_onclick = async function () {
    try {
        // scwin.getPar = fn_GetParIsur;
        // scwin.setPar = fn_SetParIsur;

        // 기업인수목적 회사와 주권 목록을 나눔 2010.05.30
        if (scwin.pMenuID === "ULDSTF05201") {
            const res = await $c.lc.popFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
            ibx_comNm.setValue(res.COM_NM);
            ibx_isurCd.setValue(res.ISUR_CD);
            scwin.fr_SecuGrpId = res.SECUGRP_ID;
            // {STYPE: pSType, SECU_GRP_STR: secuGrpStr, SECJ_GRP_ID: pSecjGrpId }

            // grid 헤드 세팅
            $c.lc.gridNameChange(scwin.fr_SecuGrpId, "grd_IssRecv", "grd_IssList");

            scwin.vSpotIsuTrdMktTpCd = res.SPOT_ISU_TRD_MKT_TP_CD;
            scwin.vSYMBL_INPUT_CD = scwin.vSpotIsuTrdMktTpCd;
            await scwin.setSymblObj();

        } else if (scwin.pMenuID === "ULDSTF05256") {
            // 기업인수목적 회사
            const res = await $c.lc.popFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
            ibx_comNm.setValue(res.COM_NM);
            ibx_isurCd.setValue(res.ISUR_CD);

            // grid 헤드 세팅
            $c.lc.gridNameChange(scwin.fr_SecuGrpId, "grd_IssRecv", "grd_IssList");

            scwin.vSpotIsuTrdMktTpCd = res.SPOT_ISU_TRD_MKT_TP_CD;
            scwin.vSYMBL_INPUT_CD = scwin.vSpotIsuTrdMktTpCd;
            await scwin.setSymblObj();

        } else {
            const res = await $c.lc.popFindCorpChrg(scwin.fr_SecuGrpId);
            ibx_comNm.setValue(res.comNm);
            ibx_isurCd.setValue(res.isurCd);

            // grid 헤드 세팅
            $c.lc.gridNameChange(scwin.fr_SecuGrpId, "grd_IssRecv", "grd_IssList");

            scwin.vSpotIsuTrdMktTpCd = res.spotIsuTrdMktTpCd;
            scwin.vSYMBL_INPUT_CD = scwin.vSpotIsuTrdMktTpCd;
            await scwin.setSymblObj();
        }

        scwin.btn_search_onclick();
        // fn_PopFindCorpChrg(fr_SecuGrpId);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.btn_comNm_onclick" });
    }
};

/**
 * @method
 * @name btn_isurSymbl_onclick
 * @description [상호변경] 영문회사심볼 중복체크 — 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_isurSymbl_onclick = async function () {
    try {
        if (ibx_afchgIsurSymbl.getValue() === "") {
            await $c.win.alert($c.data.getMessage("com_req_input", "영문회사심볼"));
            ibx_afchgIsurSymbl.focus();
            return false;
        } else {
            await $c.lc.chkCorpSymblDoubleInput(ibx_afchgIsurSymbl.getValue(), ibx_isurCd.getValue());
            if (!$c.util.isEmpty($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"))) {
                $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.btn_isurSymbl_onclick" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 조회 버튼 — 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function () {
    try {
        if (ibx_isurCd.getValue() === "") {
            $c.win.alert($c.data.getMessage("com_req_select", "회사"));
            ibx_isurCd.focus();
            return;
        }

        let nIndex = MxTab_1.getSelectedTabIndex();
        if (nIndex === 0) {
            // 상호변경
            await scwin.conmChgReadSync();
        } else if (nIndex === 1) {
            // 주식발행내역
            await scwin.issListSync();
            // dts_IssList.setRowPosition(dts_IssList.getTotalRow(), 0);
            // dts_IssRecv.setRowPosition(dts_IssRecv.getTotalRow(), 0);
            dlt_stkIsuExtrDtlListResDto.setRowPosition(0);
            dlt_stkIsuDtlListResDto.setRowPosition(0);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_issNew_onclick
 * @description [주식발행내역] 신규 버튼 — 「신규」 클릭 이벤트
