};

/**
 * @method
 * @name btn_excel1_onclick
 * @description [주식발행내역] 변경상장신청내역 엑셀다운로드 버튼 — 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_excel1_onclick = function (e) {
    try {
        $c.data.downloadGridViewExcel(grd_IssRecv, {fileName: "변경상장신청내역", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05201.btn_excel1_onclick" });
    }
};

