/**
 * @method
 * @name trs
 * @description 트랜잭션 객체 처리(레거시).
 * @param {Number} trsIdx 번호/개수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function (trsIdx) {

    let action = "";
    if (scwin.TR_JOB === "I") {
        action = "/api/listing/lstproc/stock/chglisting/insert";
    } else if (scwin.TR_JOB === "U") {
        action = "/api/listing/lstproc/stock/chglisting/update";
    } else if (scwin.TR_JOB === "D") {
        action = "/api/listing/lstproc/stock/chglisting/delete";
    }

    dlt_isuNmChgListResDto.setBroadcast(false);
    for (let i = 0; i < dlt_isuNmChgListResDto.getRowCount(); i++) {
        dlt_isuNmChgListResDto.setCellData(i, "bzProcsNo", scwin.vBzProcsNo);
        // const newBzProcNo = await getNewBzProcNo();
        // dlt_isuNmChgListResDto.setCellData(i, "bzProcsNo", newBzProcNo);
        dlt_isuNmChgListResDto.setCellData(i, "mktactEnforceDd", dma_comNmChgListResDto.get("mktactEnforceDd"));
        dlt_isuNmChgListResDto.setCellData(i, "dma_comNmChgListResDto", dma_comNmChgListResDto.get("dma_comNmChgListResDto"));
    }
    dlt_isuNmChgListResDto.setBroadcast(true, true);

    dma_saveReq.set("bzProcsNo", scwin.vBzProcsNo);
    dma_saveReq.set("listBzTpCd", "148");
    dma_saveReq.set("count", "2");
    dma_saveReq.set("comNmChgReqDto", dma_comNmChgListResDto.getJSON()); // 저장용으로 dma 만들어 줘야함
    dma_saveReq.set("isuNmChgReqDto", dlt_isuNmChgListResDto.getAllJSON());
    const sbmOptions = {
        id: "sbm_save",
        action: action,
        method: "post",
        ref: "dma_saveReq",
        // target: "dma_saveRes=body",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);

    dma_saveReq.setEmptyValue();
    if (res.responseJSON.success) {
        await scwin.conmChgReadSync();
        if (scwin.TR_JOB === "D") {
            $c.win.alert($c.data.getMessage("com_complete_0150", "삭제"));
        } else {
            let chgTyp = dma_comNmChgListResDto.get("comChgRsnCd");
            if ((chgTyp === "11") || (chgTyp === "12")) {
                // 영문상호, 약명변경
                if (scwin.market === '2' || scwin.market === "6") {
                    let msg = "상호변경 및 종목명변경이 성공적으로 처리되었습니다. \r\n\r\n" + "안내문작성 버튼을 선택하여 안내문을 작성 하시기 바랍니다.";
                    await $c.win.alert(msg);
                } else {
                    // fn_alertMsg('S') ;
                    let msg = "상호변경 및 종목명변경이 성공적으로 처리되었습니다.";
                    await $c.win.alert(msg);
                }
            } else {
                let msg = "상호변경 및 종목명변경이 성공적으로 처리되었습니다. \r\n\r\n" + "주식발행내역 화면으로 이동하시어 주식발행자료를 등록(주식발행사유:상호변경) 후 상호변경 공시를 하시기 바랍니다.\r\n\r\n" + "주식발행내역 화면으로 이동하시겠습니까?" + "";
                let res = await $c.win.confirm(msg);
                if (res) {
                    MxTab_1.setSelectedTabIndex(1);
                    // btn_issNew.onclick();
                }
            }
        }
    }

};

/**
 * @method
 * @name dscl
 * @description [상호변경] 안내문 작성 팝업
 * @returns {Promise<*>} 결과 값
 * @hidden N
 */
scwin.dscl = async function () {
    $c.win.alert("공시 안내문 작성");
    return;

    let OldGet = scwin.getPar;
    let OldSet = scwin.setPar;
    if ((ibx_isurCd.getValue() === "") || (cal_mktactEnforceDd.getValue() === "")) {
        $c.win.alert("발행기관 코드 혹은 변경상장일 자료가 없습니다.");
        return;
    }
    if (scwin.vBzProcsNo === "") {
        $c.win.alert("먼저 저장하신후 선택하시기 바랍니다.");
        return;
    }
    if ($c.cp.isModified(dts_CoNm) || $c.cp.isModified(dlt_isuNmChgListResDto)) {
        $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    let chgTyp = dma_comNmChgListResDto.get("comChgRsnCd");
    if ((chgTyp === "11") || (chgTyp === "12")) {
        // 영문상호, 약명변경

        //  코스닥만 안내공시하다가  종목명변경 메뉴를 삭제해서 유가도 안내공시 기능추가 2009.07.17
        if (scwin.vSpotIsuTrdMktTpCd === '1') {
            let OldGet = scwin.getPar;
            let OldSet = scwin.setPar;
            scwin.getPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
                arr[0] = "68959"; // 68926:기타안내사항 -> 689599:종목명 변경) 으로 서식코드변경
                arr[1] = scwin.vBzProcsNo;
                arr[2] = ibx_isurCd.getValue();
                arr[3] = $c.lc.getMktId();
                arr[4] = scwin.getIsuNmDisclsCtnt();
                arr[5] = '';

                // CopyDataSet( dts_Delistdetail , param_dts_isu) ;
                // CopyDataSet( dts_Isu , param_dts_mst) ;
                return arr.length;
            };
            scwin.setPar = function (arr) {

            };
            let wth = 730 + 5;
            let hgt = 785 + 30;
            // TODO Stage2: 레거시 모달 좌표 계산 — openPopup 은 위치 옵션으로 대체
            let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
            // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
            scwin.getPar = OldGet;
            scwin.setPar = OldSet;
        } else if (scwin.vSpotIsuTrdMktTpCd === '2' || scwin.vSpotIsuTrdMktTpCd === "6") {
            const sbmOptions = {
                id : "sbm_dts_dscl",
                action : "/listingCommon.do",
                ref : "",
                target : "dts_dscl=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            const sbmOptions2 = {
                id : "sbm_dts_dscl_Eng",
                action : "/listingCommon.do",
                ref : "",
                target : "dts_dscl_Eng=body.content",
                isProcessMsg : false
            };

            const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
            // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
                arr[0] = "70792";
                arr[1] = vBzProcsNo;
                arr[2] = ibx_isurCd.value ;

                CopyDataSet(dts_dscl, param_dts_mst);
                return arr.length;
            }
             */

            /* 2009.06.12 영문공시관련추가 */
            scwin.getPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
                if (scwin.vSpotIsuTrdMktTpCd === "2") {
                    arr[0] = "70792";
                } else {
                    arr[0] = "32009";
                }
                arr[1] = scwin.vBzProcsNo;
                arr[2] = ibx_isurCd.getValue();
                $c.stf.copyDataSet(dts_dscl, param_dts_mst);
                $c.stf.copyDataSet(dts_dscl_Eng, param_dts_mst_eng);
                return arr.length;
            };
            /* 2009.06.12 영문공시관련추가 */

            // $c.win.alert("dts_dscl.Text-->"+dts_dscl.Text);
            // $c.win.alert("dts_dscl_Eng.Text-->"+dts_dscl_Eng.Text);

            scwin.setPar = function (arr) {

            };
            let wth = 730 + 5;
            let hgt = 785 + 30;
            // TODO Stage2: 레거시 모달 좌표 계산 — openPopup 은 위치 옵션으로 대체
            let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
            // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
            scwin.getPar = OldGet;
            scwin.setPar = OldSet;
        }
    } else {
        $c.win.alert("상호변경사유가 [영문상호변경], [약명변경]일 경우에만 안내문작성이 가능합니다.\r\n\r\n" + "나머지사유는 주식발행내역 화면으로 이동하시어 주식발행자료를 등록(주식발행사유:상호변경) 후 상호변경 안내공시를 하시기 바랍니다 ");
    }
};

