/**
 * @method
 * @name setSymblObj
 * @description 영문회사심볼 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setSymblObj = function () {
    if (scwin.vSYMBL_INPUT_CD === '1') {
        panel_isurSymbl.show();
        grd_isuNm.setColumnVisible("bfchgIsuEngSymbl", true);
        grd_isuNm.setColumnVisible("afchgIsuEngSymbl", true);
        grd_hisCoNm.setColumnVisible("afchgIsurSymbl", true);
        grd_hisIsuNm.setColumnVisible("afchgIsuEngSymbl", true);

    } else if (scwin.vSYMBL_INPUT_CD === '2' || scwin.vSYMBL_INPUT_CD === "6") {
        panel_isurSymbl.hide();
        grd_isuNm.setColumnVisible("bfchgIsuEngSymbl", false);
        grd_isuNm.setColumnVisible("afchgIsuEngSymbl", false);
        grd_hisCoNm.setColumnVisible("afchgIsurSymbl", false);
        grd_hisIsuNm.setColumnVisible("afchgIsuEngSymbl", false);

    }
};

