/**
 * @method
 * @name checkForm
 * @description [상호변경] 입력데이터 확인
 * @returns {Promise<Boolean>} 판정 결과
 * @hidden N
 */
scwin.checkForm = async function () {
    let vCurDate = $c.date.getServerDateTime();

    // 컴포넌트 객체 전달
    $c.date.checkCalendarFormat("cal_mktactEnforceDd", "yyyyMMdd");

    if (ibx_isurCd.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_select", "회사"));
        ibx_isurCd.focus();
        return false;
    }
    if (cal_mktactEnforceDd.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "변경상장일"));
        cal_mktactEnforceDd.focus();
        return false;
    }
    if (vCurDate >= cal_mktactEnforceDd.getValue()) {
        await $c.win.alert($c.data.getMessage("com_req_input", "변경상장일을 현재일이후로 "));
        cal_mktactEnforceDd.focus();
        return false;
    }
    if (sbx_comChgRsnCd.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_select", "변경사유"));
        sbx_comChgRsnCd.focus();
        return false;
    }
    if (ibx_afchgComNm.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "한글회사명"));
        ibx_afchgComNm.focus();
        return false;
    }

    if (!$c.stf.checkMaxLength(ibx_afchgComNm, 60, "한글회사명")) return false;

    if (ibx_afchgComAbbrv.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "한글회사약명"));
        ibx_afchgComAbbrv.focus();
        return false;
    }

    if (!$c.stf.checkMaxLength(ibx_afchgComAbbrv, 30, "한글회사약명")) return false;

    if (ibx_afchgComEngNm.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "영문회사명"));
        ibx_afchgComEngNm.focus();
        return false;
    }

    if (!$c.stf.checkMaxLength(ibx_afchgComEngNm, 60, "영문회사명")) return false;

    if (ibx_afchgComEngAbbrv.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "영문회사약명"));
        ibx_afchgComEngAbbrv.focus();
        return false;
    }

    if (!$c.stf.checkMaxLength(ibx_afchgComEngAbbrv, 30, "영문회사약명")) return false;

    if (scwin.vSYMBL_INPUT_CD === '1') {
        if (ibx_afchgIsurSymbl.getValue() === "") {
            await $c.win.alert($c.data.getMessage("com_req_input", "영문회사심볼"));
            ibx_afchgIsurSymbl.focus();
            return false;
        }
        if (! await $c.lc.chkCorpSymblDoubleInput(ibx_afchgIsurSymbl.getValue(), ibx_isurCd.getValue())) {
            $c.win.alert($c.lc.getGlbValue("MSG_SYMBL_DOUBLE_INPUT"));
            return false;
        }
    }

    /* 2009-04-24 상호변경 중복입력체크 */
    ///*
    if (! await $c.lc.checkBzDoubleInput(ibx_isurCd.getValue(), cal_mktactEnforceDd.getValue(), scwin.vBzProcsNo, "148")) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (dlt_isuNmChgListResDto.getCellData(0, "afchgIsuKorNm") === "") {
            $c.win.alert($c.data.getMessage("com_select_0085"));
            return;
        }
        if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
        if (String(scwin.vBzProcsNo).length !== 14) {
            $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
        } else {
            dma_comNmChgListResDto.set("bzProcsNo", scwin.vBzProcsNo);
            dma_comNmChgListResDto.set("isurCd", ibx_isurCd.getValue());
            scwin.trs($c.lc.getGlbValue("TRS_IDX_INSERT"));
        }
    }
};

/**
 * @method
 * @name update
 * @description 입력값을 수정 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
        scwin.trs($c.lc.getGlbValue("TRS_IDX_UPDATE"));
    }
};

/**
 * @method
 * @name delete
 * @description 선택 자료를 삭제한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function () {
    scwin.TR_JOB = 'D';
    if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
    // buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.
    scwin.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trs($c.lc.getGlbValue("TRS_IDX_DELETE"));
};

/**
 * @method
 * @name getIsuNmDisclsCtnt
 * @description 종목명 변경 공시 내용을 구성한다.
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getIsuNmDisclsCtnt = function () {
    let vCtnt = "";
    vCtnt += "\r\n";
    vCtnt += "1. 변경내역(변경전 → 변경후)";
    vCtnt += "\r\n";
    vCtnt += "    - 한글종목명";
    vCtnt += "\r\n";
    for (let i = 1; i <= dlt_isuNmChgListResDto.getRowCount(); i++) {
        vCtnt += "         o " + dlt_isuNmChgListResDto.getCellData(i, "bfchgIsuKorNm") + " → " + dlt_isuNmChgListResDto.getCellData(i, "afchgIsuKorNm");
        vCtnt += "\r\n";
    }
    vCtnt += "    - 영문종목명";
    vCtnt += "\r\n";
    for (let i = 1; i <= dlt_isuNmChgListResDto.getRowCount(); i++) {
        vCtnt += "         o " + dlt_isuNmChgListResDto.getCellData(i, "bfchgIsuEngNm") + " → " + dlt_isuNmChgListResDto.getCellData(i, "afchgIsuEngNm");
        vCtnt += "\r\n";
    }
    vCtnt += "2. 변경일자: " + scwin.dateForm(cal_mktactEnforceDd.getValue());
    vCtnt += "\r\n";
    vCtnt += "3. 변경사유: ★★★★★★★★★★★★";
    vCtnt += "\r\n";
    return vCtnt;
};

/**
 * @method
 * @name dateForm
 * @description 일자 문자열을 yyyy-MM-dd 표시 형식으로 바꾼다.
 * @param {*} pStr pStr
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.dateForm = function (pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    }
    return str;
};

/**
 * @method
 * @name changeIsuNmByBatch
 * @description [상호변경] 종목명자동생성 세팅
 * @returns {Promise<Boolean>} 판정 결과
 * @hidden N
 */
scwin.changeIsuNmByBatch = async function () {
    if (!await scwin.checkForm()) return false;
    // grd_isuNmredraw = false;
    let gAfComNm = ibx_afchgComNm.getValue();
    let repCoNm = gAfComNm.replace("(주)", "");
    repCoNm = repCoNm.replace("㈜", "");
    repCoNm = repCoNm.replace("주식회사", "");
    let gAfComEngNm = ibx_afchgComEngNm.getValue();
    let repCoEngNm = gAfComEngNm.replace("CO., LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO., LTD", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD", "");
    repCoEngNm = repCoEngNm.replace("Co., Ltd", "");
    dlt_isuNmChgListResDto.setBroadcast(false);
    for (let i = 0; i < dlt_isuNmChgListResDto.getRowCount(); i++) {
        let gStkcertKndCd = dlt_isuNmChgListResDto.getCellData(i, "stkcertKindCd");
        await scwin.stkkndcdReadSync(gStkcertKndCd);
        let vPreStr = "";
        let vPreEngStr = "";
        let gCompressCD = "";
        if (gStkcertKndCd !== '000') {
            gCompressCD = dma_selectOneStkcertKindRes.get("compressCd");
        }
        let vStkKndSNm = dma_selectOneStkcertKindRes.get("stkKndSnm");
        let vStkKndEngNm = dma_selectOneStkcertKindRes.get("stkKndEngNm");
        let vStkKndEngSNm = dma_selectOneStkcertKindRes.get("stkKndEngSnm");
        let gPrefStkTpCd = dlt_isuNmChgListResDto.getCellData(i, "prefstkTpCd");
        if (gPrefStkTpCd === '2') {
            vPreStr = "(신형)";
            vStkKndSNm = vStkKndSNm + "B";
            vStkKndEngNm = vStkKndEngNm.replace("P", "PB");
            vStkKndEngSNm = vStkKndEngSNm.replace("P", "PB");
        }
        dlt_isuNmChgListResDto.setCellData(i, "afchgIsuKorNm", repCoNm + dma_selectOneStkcertKindRes.get("stkKndNm") + vPreStr);
        dlt_isuNmChgListResDto.setCellData(i, "afchgIsuKorAbbrv", ibx_afchgComAbbrv.getValue() + vStkKndSNm);
        dlt_isuNmChgListResDto.setCellData(i, "afchgIsuEngNm", repCoEngNm + vStkKndEngNm);
        dlt_isuNmChgListResDto.setCellData(i, "afchgIsuEngAbbrv", ibx_afchgComEngAbbrv.getValue() + vStkKndEngSNm);
        dlt_isuNmChgListResDto.setCellData(i, "afchgIsuEngSymbl", ibx_afchgIsurSymbl.getValue() + gCompressCD);
    }
    dlt_isuNmChgListResDto.setBroadcast(true, true);
    grd_isuNm.redraw = true;
    return true;
};

/**
 * @method
 * @name openDetailExtr
 * @description [주식발행내역] 변경상장신청내역 - 주식발행관리 팝업
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailExtr = async function (row) {
    let secugrpId = scwin.fr_SecuGrpId;
    scwin.clickBzProcsNo = ""; // 초기화
    scwin.gAcptNo = dlt_stkIsuExtrDtlListResDto.getCellData(row, "acptNo");
    scwin.gAcptNoListFee = scwin.gAcptNo;
    // gAcptNo = "20080616007146";
    scwin.gAcptSeq = dlt_stkIsuExtrDtlListResDto.getCellData(row, "BYACPTNO_SEQ");

    const data = {
        fr_SecuGrpId: scwin.fr_SecuGrpId,
        clickBzProcsNo: scwin.clickBzProcsNo,
        gAcptNo: scwin.gAcptNo,
        gAcptSeq: scwin.gAcptSeq,
        gAcptNoListFee: scwin.gAcptNoListFee,
        vPageTYp: scwin.vPageTYp,
        vSpotIsuTrdMktTpCd: scwin.vSpotIsuTrdMktTpCd,
        isurCd: ibx_isurCd.getValue(),
        comNm: ibx_comNm.getValue(),
    };
    const res = await $c.lc.openDetailIssMngChg(ibx_isurCd, scwin.fr_SecuGrpId, data);
    if (res) {
        scwin.openDetailIssMngChgCallback(res.vSecugrpID);
    }
};

/**
 * @method
 * @name openDetailCorpIsu
 * @description [주식발행내역] 상장종목팝업창
